WITH flattened_attrs AS (SELECT id, service, log_ts, level, latency_ms, status_code, context, COALESCE(context['trace'], 'direct') AS trace_or_default, COALESCE(context['version'], 'direct') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, CAST((status_code & 1) != 0 AS INT) AS flag_bit1 FROM app_logs) SELECT DATE_TRUNC('DAY', log_ts) AS activity_day, CASE WHEN status_code >= 455 THEN 'LARGE' ELSE 'SMALL' END AS status_code_tier, service, COUNT(*) AS cnt, BIT_AND(latency_ms) AS latency_ms_bit_and, CORR(status_code, latency_ms) AS corr_status_code_latency_ms, ROUND(SUM(latency_ms) / NULLIF(COUNT(CASE WHEN service = 'checkout' THEN 1 END), 0), 2) AS latency_ms_per_checkout FROM flattened_attrs GROUP BY 1, 2, 3 ORDER BY latency_ms_bit_and DESC;
